<script setup lang="ts">
import {computed,onScopeDispose,ref,watch} from 'vue'
import {projectId} from '@/core/session'
import {ApiError,errorMessage,identityEpoch,onIdentityChange} from '@/core/http'
import {taskModbusTcpCommon,previewTaskModbusTcp,taskModbusTcpFrame,type TaskModbusTcpCommon} from './task-modbus-tcp-common'
import {taskModbusNumberAttributes} from './task-modbus-rtu-common'
import type {TaskSelectionWrite} from './models'
const props=defineProps<{modelValue:boolean;value?:unknown;selection?:TaskSelectionWrite;busy?:boolean;locked?:boolean;pending?:boolean;error?:string}>()
const emit=defineEmits<{'update:modelValue':[value:boolean];save:[value:TaskModbusTcpCommon];verify:[];busy:[value:boolean];denied:[cause:ApiError]}>()
const unit=ref<number>(),code=ref(''),address=ref(''),quantity=ref(1),registerValue=ref(''),valueHex=ref(false),hex=ref(true),localError=ref(''),preview=ref(''),previewBusy=ref(false)
const useAttributes=ref(false),registerAttribute=ref(''),registerAttributes=ref<string[]>([]),candidateError=ref('')
const registerValues=ref<string[]>([]),registerHex=ref<boolean[]>([])
const coilValues=ref<number[]>([])
const allCoils=computed({get:()=>coilValues.value.length>0&&coilValues.value.every(value=>value===1)?1:0,set:(value:number)=>{if(!blocked.value&&(value===0||value===1))coilValues.value=coilValues.value.map(()=>value)}})
const units=Array.from({length:255},(_,i)=>({value:i+1,label:`${i+1} - 0x${(i+1).toString(16).toUpperCase().padStart(2,'0')}`}))
const functions=[['01','读线圈'],['02','读离散输入'],['03','读保持寄存器'],['04','读输入寄存器'],['05','写单个线圈'],['06','写单个寄存器'],['0F','写多个线圈'],['10','写多个寄存器']]
const blocked=computed(()=>!!(props.busy||props.locked||props.pending||previewBusy.value)),countLabel=computed(()=>['01','02','0F'].includes(code.value)?'线圈个数':'寄存器个数')
let controller:AbortController|undefined,candidateController:AbortController|undefined,generation=0,candidateTurn=0
function stopSuggestions(){candidateTurn++;candidateController?.abort();candidateController=undefined;candidateError.value=''}
watch(()=>JSON.stringify(props.selection),()=>{stopSuggestions();abort();preview.value=''})
function abort(){stopSuggestions();generation++;controller?.abort();controller=undefined;previewBusy.value=false;emit('busy',false)}
watch(()=>props.modelValue,()=>{abort();unit.value=undefined;code.value='';address.value='';quantity.value=1;useAttributes.value=false;registerAttribute.value='';registerAttributes.value=[];coilValues.value=[];registerValues.value=[];registerHex.value=[];registerValue.value='';valueHex.value=false;hex.value=true;localError.value='';preview.value='';if(props.modelValue&&props.value!==undefined)try{const v=taskModbusTcpCommon(props.value);unit.value=v.unitId;code.value=v.functionCode;address.value=v.registerAddress.toString(16).toUpperCase().padStart(4,'0');if('registerAttribute' in v){useAttributes.value=true;registerAttribute.value=v.registerAttribute}else if('registerAttributes' in v){useAttributes.value=true;registerAttributes.value=[...v.registerAttributes];quantity.value=registerAttributes.value.length}else if(v.functionCode==='10'){registerValues.value=v.registerValues.map(String);registerHex.value=v.registerValues.map(()=>false);quantity.value=registerValues.value.length}else if(v.functionCode==='0F'){coilValues.value=[...v.coilValues];quantity.value=coilValues.value.length}else if(v.functionCode==='05'||v.functionCode==='06')registerValue.value=String(v.registerValue);else quantity.value=v.quantity}catch(cause){localError.value=errorMessage(cause)}},{immediate:true})
watch(projectId,clearScope)
const unsubscribe=onIdentityChange(clearScope)
function clearScope(){abort();useAttributes.value=false;registerAttribute.value='';registerAttributes.value=[];coilValues.value=[];registerValues.value=[];registerHex.value=[];unit.value=undefined;code.value='';address.value='';registerValue.value='';preview.value='';localError.value=''}
watch([unit,code,address,quantity,registerValue,useAttributes,registerAttribute],()=>{preview.value=''})
watch(registerAttributes,()=>{preview.value=''},{deep:true})
watch(coilValues,()=>{preview.value=''},{deep:true})
watch([registerValues,registerHex],()=>{preview.value=''},{deep:true})
/** 改数量只保留原序前缀，新显示项明确为关闭；保存仍由严格列表校验。 */
function resizeCoils(){if(code.value!=='0F'||!Number.isInteger(quantity.value)||quantity.value<1||quantity.value>64)return;coilValues.value=Array.from({length:quantity.value},(_,i)=>coilValues.value[i]??0)}
watch([code,quantity],resizeCoils)
/** 寄存器扩缩保持已显示的原序与进制；新项是明确的十进制零，不截断非法值。 */
function resizeRegisters(){if(code.value!=='10'||!Number.isInteger(quantity.value)||quantity.value<1||quantity.value>64)return;registerValues.value=Array.from({length:quantity.value},(_,i)=>registerValues.value[i]??'0');registerHex.value=Array.from({length:quantity.value},(_,i)=>registerHex.value[i]??false);registerAttributes.value=Array.from({length:quantity.value},(_,i)=>registerAttributes.value[i]??'')}
watch([code,quantity],resizeRegisters)
function registerWords(){if(!Number.isInteger(quantity.value)||quantity.value<1||quantity.value>64||quantity.value!==registerValues.value.length)throw new Error('请配置1至64个完整寄存器值。');return registerValues.value.map((text,i)=>{if(!(registerHex.value[i]?/^[0-9A-Fa-f]{1,4}$/:/^\d{1,5}$/).test(text))throw new Error('请填写正确的寄存器值。');return parseInt(text,registerHex.value[i]?16:10)})}
function registerItemMode(index:number,next:boolean){if(blocked.value)return;const text=registerValues.value[index];try{if(text===undefined||text&&!(registerHex.value[index]?/^[0-9A-Fa-f]{1,4}$/:/^\d{1,5}$/).test(text))throw new Error();const previous=text?parseInt(text,registerHex.value[index]?16:10):undefined;if(previous!==undefined&&(previous<0||previous>65535))throw new Error();registerHex.value[index]=next;registerValues.value[index]=previous===undefined?'':previous.toString(next?16:10).toUpperCase().padStart(next?4:1,'0')}catch{registerHex.value[index]=next;registerValues.value[index]=''}}
async function suggestions(search:string,done:(items:{value:string;name:string}[])=>void){
 candidateController?.abort();const selection=props.selection,project=projectId.value,epoch=identityEpoch(),turn=++candidateTurn,key=JSON.stringify(selection)
 if(!props.modelValue||blocked.value||!selection||search.length>64){done([]);return}
 candidateController=new AbortController();const signal=candidateController.signal;candidateError.value=''
 const current=()=>!signal.aborted&&props.modelValue&&project===projectId.value&&epoch===identityEpoch()&&turn===candidateTurn&&key===JSON.stringify(props.selection)
 try{const rows=await taskModbusNumberAttributes(project,selection,search,signal);if(current())done(rows)}catch{if(current()){candidateError.value='设备属性建议暂不可用。';done([])}}
}
onScopeDispose(()=>{unsubscribe();abort()})
function value(){if(!/^(?:[0-9A-Fa-f]{1,4})$/.test(address.value)&&hex.value||!/^\d{1,5}$/.test(address.value)&&!hex.value)throw new Error('请填写正确的起始寄存器地址。');if(code.value==='0F'&&(!Number.isInteger(quantity.value)||quantity.value<1||quantity.value>64||quantity.value!==coilValues.value.length))throw new Error('请配置完整的线圈数量与状态。');if(useAttributes.value&&(code.value==='06'||code.value==='10')){if(code.value==='10'&&quantity.value!==registerAttributes.value.length)throw new Error('请配置完整的设备属性标识符。');return taskModbusTcpCommon({schemaVersion:2,kind:'MODBUS_TCP',unitId:unit.value,functionCode:code.value,registerAddress:parseInt(address.value,hex.value?16:10),...(code.value==='06'?{registerAttribute:registerAttribute.value}:{registerAttributes:[...registerAttributes.value]}),transactionId:0})}let word:number|undefined;if(code.value==='05'||code.value==='06'){if(!(valueHex.value?/^[0-9A-Fa-f]{1,4}$/:/^\d{1,5}$/).test(registerValue.value))throw new Error(code.value==='05'?'请填写正确的线圈值。':'请填写正确的寄存器值。');word=parseInt(registerValue.value,valueHex.value?16:10)}return taskModbusTcpCommon({schemaVersion:1,kind:'MODBUS_TCP',unitId:unit.value,functionCode:code.value,registerAddress:parseInt(address.value,hex.value?16:10),...(code.value==='10'?{registerValues:registerWords()}:code.value==='0F'?{coilValues:[...coilValues.value]}:code.value==='05'||code.value==='06'?{registerValue:word}:{quantity:quantity.value}),transactionId:0})}
function registerMode(next:boolean){if(blocked.value)return;try{if(registerValue.value&&!(valueHex.value?/^[0-9A-Fa-f]{1,4}$/:/^\d{1,5}$/).test(registerValue.value))throw new Error();const previous=registerValue.value?parseInt(registerValue.value,valueHex.value?16:10):undefined;if(previous!==undefined&&(previous<0||previous>65535))throw new Error();valueHex.value=next;registerValue.value=previous===undefined?'':previous.toString(next?16:10).toUpperCase().padStart(next?4:1,'0')}catch{valueHex.value=next;registerValue.value=''}}
function mode(next:boolean){if(blocked.value)return;try{if(address.value&&!(hex.value?/^[0-9A-Fa-f]{1,4}$/:/^\d{1,5}$/).test(address.value))throw new Error();const previous=address.value?parseInt(address.value,hex.value?16:10):undefined;if(previous!==undefined&&previous>65535)throw new Error();hex.value=next;address.value=previous===undefined?'':previous.toString(next?16:10).toUpperCase().padStart(next?4:1,'0')}catch{hex.value=next;address.value=''}}
function close(){if(props.busy||props.pending||previewBusy.value)return;abort();emit('update:modelValue',false)}
function save(){if(blocked.value)return;try{emit('save',value());localError.value=''}catch(cause){localError.value=errorMessage(cause)}}
async function generate(){if(blocked.value)return;let turn:number|undefined,signal:AbortSignal|undefined;try{const config=value(),project=projectId.value,epoch=identityEpoch();if(!project)return;controller=new AbortController();signal=controller.signal;turn=++generation;previewBusy.value=true;emit('busy',true);localError.value='';const result=await previewTaskModbusTcp(project,config,signal,props.selection);if(signal.aborted||turn!==generation||!props.modelValue||project!==projectId.value||epoch!==identityEpoch())return;if(result.status!=='SUCCESS'||result.outputJson===null)throw new Error(result.errorCode||'生成预览失败。');preview.value=taskModbusTcpFrame(config,result.outputJson)}catch(cause){if(signal?.aborted||turn!==undefined&&turn!==generation)return;localError.value=errorMessage(cause);if(cause instanceof ApiError&&[401,403,404].includes(cause.status))emit('denied',cause)}finally{if(turn!==undefined&&turn===generation){previewBusy.value=false;emit('busy',false)}}}
</script>
<template>
 <el-dialog :model-value="modelValue" title="配置操作" width="min(800px,94vw)" :lock-scroll="false" :close-on-click-modal="false" :close-on-press-escape="!busy&&!pending&&!previewBusy" :show-close="!busy&&!pending&&!previewBusy" destroy-on-close append-to-body @update:model-value="close">
  <el-form v-if="modelValue" label-position="top" :disabled="blocked" @submit.prevent="save">
   <el-row :gutter="10"><el-col :span="12"><el-form-item label="从机地址"><el-select v-model="unit" style="width:100%" size="small" aria-label="TCP从机地址" placeholder="请选择从机地址"><el-option v-for="item in units" :key="item.value" :value="item.value" :label="item.label"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="功能码"><el-select v-model="code" style="width:100%" size="small" aria-label="TCP功能码" placeholder="请选择功能码"><el-option v-for="[value,label] in functions" :key="value" :value="value" :label="value+' '+label"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="起始寄存器地址"><el-switch :model-value="hex" active-text="Hex" inactive-text="Dec" aria-label="TCP地址进制" @update:model-value="mode($event===true)"/><el-input v-model="address" size="small" aria-label="TCP起始寄存器地址" :maxlength="hex?4:5"/></el-form-item></el-col><el-col v-if="code!=='05'&&code!=='06'" :span="12"><el-form-item :label="countLabel"><el-input-number v-model="quantity" style="width:100%" size="small" controls-position="right" :min="1" :max="64" :aria-label="code==='10'?'TCP寄存器数量':code==='0F'?'TCP线圈数量':'TCP读取数量'"/></el-form-item></el-col><el-col v-else-if="code!=='06'||!useAttributes" :span="12"><el-form-item :label="code==='05'?'线圈值':'寄存器值'"><el-switch :model-value="valueHex" active-text="Hex" inactive-text="Dec" :aria-label="code==='05'?'TCP线圈值进制':'TCP寄存器值进制'" @update:model-value="registerMode($event===true)"/><el-input v-model="registerValue" size="small" :aria-label="code==='05'?'TCP线圈值':'TCP寄存器值'" :maxlength="valueHex?4:5"/></el-form-item></el-col><template v-if="code==='0F'"><el-col :span="24"><el-form-item label="全开或全关"><el-switch v-model="allCoils" :active-value="1" :inactive-value="0" aria-label="TCP全开或全关"/></el-form-item></el-col><el-col v-for="(_,i) in coilValues" :key="i" :span="6"><el-form-item :label="'#'+i+' 线圈状态值'"><el-switch v-model="coilValues[i]" :active-value="1" :inactive-value="0" :aria-label="'TCP线圈状态'+i"/></el-form-item></el-col></template><template v-if="code==='10'&&!useAttributes"><el-col v-for="(_,i) in registerValues" :key="i" :span="12"><el-form-item :label="'#'+i+' 寄存器值'"><el-switch :model-value="registerHex[i]" active-text="Hex" inactive-text="Dec" :aria-label="'TCP寄存器进制'+i" @update:model-value="registerItemMode(i,$event===true)"/><el-input v-model="registerValues[i]" size="small" :aria-label="'TCP寄存器值'+i" :maxlength="registerHex[i]?4:5"/></el-form-item></el-col></template><el-col v-if="code==='06'||code==='10'" :span="24"><el-form-item><template #label>使用设备属性值 <el-tooltip content="不指定固定的寄存器值，而是使用任务运行时的设备属性值，作为寄存器写入值。"><span class="help-mark" tabindex="0">?</span></el-tooltip></template><el-switch v-model="useAttributes" aria-label="TCP使用设备属性值"/></el-form-item></el-col><template v-if="useAttributes&&(code==='06'||code==='10')"><el-col v-for="(_,i) in code==='06'?[registerAttribute]:registerAttributes" :key="i" :span="12"><el-form-item><template #label>{{code==='06'?'设备属性标识符':'#'+i+' 设备属性标识符'}} <el-tooltip content="使用任务运行时的设备属性值，作为寄存器写入值。仅支持数值型属性。"><span class="help-mark" tabindex="0">?</span></el-tooltip></template><el-autocomplete v-if="code==='06'" v-model="registerAttribute" :fetch-suggestions="suggestions" :maxlength="64" size="small" aria-label="TCP设备属性标识符" placeholder="填写属性标识符"><template #default="{item}"><span class="property-suggestion">{{item.value}}<span>{{item.name}}</span></span></template></el-autocomplete><el-autocomplete v-else v-model="registerAttributes[i]" :fetch-suggestions="suggestions" :maxlength="64" size="small" :aria-label="'TCP设备属性标识符'+i" placeholder="填写属性标识符"><template #default="{item}"><span class="property-suggestion">{{item.value}}<span>{{item.name}}</span></span></template></el-autocomplete></el-form-item></el-col></template></el-row>
   <el-button link type="primary" :loading="previewBusy" @click="generate">生成预览</el-button><section v-if="preview"><h3>Modbus 指令预览</h3><pre>{{preview}}</pre></section>
  </el-form>
  <el-alert v-if="candidateError" :title="candidateError" type="warning" :closable="false"/>
  <el-alert v-if="localError||error" :title="localError||error" type="warning" :closable="false"/>
  <template #footer><el-button :disabled="busy||pending||previewBusy" @click="close">取消</el-button><el-button v-if="pending" :disabled="busy||previewBusy" @click="emit('verify')">重新读取核对</el-button><el-button type="primary" :loading="busy" :disabled="blocked" @click="save">完成</el-button></template>
 </el-dialog>
</template>

<style scoped>
.property-suggestion{display:flex;align-items:center}.property-suggestion>span{flex:1;text-align:right;margin-left:50px;font-size:13px}.help-mark{display:inline-flex;align-items:center;justify-content:center;width:14px;height:14px;border:1px solid #909399;border-radius:50%;font-size:11px;line-height:12px;color:#909399;margin-left:5px}:deep(.el-autocomplete){width:100%}
</style>
